def containsDuplicate(nums: list[int]) -> bool:
    # Hash set gives O(1) expected lookups for seen numbers
    seen = set()
    for x in nums:
        # If already recorded, we found a duplicate
        if x in seen:
            return True
        seen.add(x)
    # Scanned entire array with all unique elements
    return False

