def searchMatrix(matrix: list[list[int]], target: int) -> bool:
    if not matrix or not matrix[0]:
        return False
    m, n = len(matrix), len(matrix[0])
    l, r = 0, m * n - 1
    # Treat 2D matrix as a virtual 1D flattened sorted array
    while l <= r:
        mid = l + (r - l) // 2
        row, col = mid // n, mid % n
        mid_val = matrix[row][col]
        if mid_val == target:
            return True
        elif mid_val < target:
            l = mid + 1
        else:
            r = mid - 1
    return False

