        self.val = val
        self.next = next

def reverseList(root: ListNode | None) -> ListNode | None:
    prev, curr = None, root
    while curr:
        # Stash next node before breaking pointer
        nxt = curr.next
        curr.next = prev  # Invert arrow
        prev = curr       # Shift prev forward
        curr = nxt        # Shift curr forward
    return prev

