def hasCycle(head: ListNode | None) -> bool:
    # Floyd's Cycle-Finding Algorithm (Tortoise and Hare)
    slow = fast = head
    while fast and fast.next:
        slow = slow.next        # 1 step
        fast = fast.next.next   # 2 steps
        # If fast catches slow, a cycle is guaranteed
        if slow == fast:
            return True
    return False

