class Codec:
    def serialize(self, root: TreeNode | None) -> str:
        # Preorder traversal encoding null markers as 'N'
        vals = []
        def dfs(node):
            if not node:
                vals.append("N")
                return
            vals.append(str(node.val))
            dfs(node.left)
            dfs(node.right)
        dfs(root)
        return ",".join(vals)

    def deserialize(self, data: str) -> TreeNode | None:
        vals = data.split(",")
        idx = 0
        def dfs():
            nonlocal idx
            if vals[idx] == "N":
                idx += 1
                return None
            node = TreeNode(int(vals[idx]))
            idx += 1
            node.left = dfs()
            node.right = dfs()
            return node
        return dfs()

