import heapq

def findKthLargest(nums: list[int], k: int) -> int:
    # Maintain a min-heap of size k
    min_heap = []
    for num in nums:
        heapq.heappush(min_heap, num)
        if len(min_heap) > k:
            heapq.heappop(min_heap)
    # The smallest among the k largest elements is the k-th largest overall
    return min_heap[0]

