def permute(nums: list[int]) -> list[list[int]]:
    res = []

    def backtrack(curr: list[int], used: list[bool]) -> None:
        if len(curr) == len(nums):
            res.append(curr.copy())
            return
        for i in range(len(nums)):
            if not used[i]:
                used[i] = True
                curr.append(nums[i])
                backtrack(curr, used)
                curr.pop()       # Backtrack
                used[i] = False

    backtrack([], [False] * len(nums))
    return res

