def partition(s: str) -> list[list[str]]:
    res = []
    part = []

    def is_pali(sub: str) -> bool:
        return sub == sub[::-1]

    def dfs(i: int) -> None:
        if i >= len(s):
            res.append(part.copy())
            return
        for j in range(i, len(s)):
            prefix = s[i : j + 1]
            if is_pali(prefix):
                part.append(prefix)
                dfs(j + 1)
                part.pop()

    dfs(0)
    return res

