        if parent[node] != node:
            parent[node] = find(parent[node])
        return parent[node]

    def union(n1: int, n2: int) -> int:
        p1, p2 = find(n1), find(n2)
        if p1 == p2:
            return 0  # No reduction in component count
        if rank[p1] > rank[p2]:
            parent[p2] = p1
            rank[p1] += rank[p2]
        else:
