def validTree(n: int, edges: list[list[int]]) -> bool:
    # A valid tree on n nodes must have exactly n - 1 edges and no cycles
    if len(edges) != n - 1:
        return False
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    for u, v in edges:
        p1, p2 = find(u), find(v)
        if p1 == p2:
            return False  # Cycle detected
        parent[p1] = p2
    return True

