def canPartition(nums: list[int]) -> bool:
    total = sum(nums)
    # If total sum is odd, cannot partition into two equal integer subsets
    if total % 2 != 0:
        return False
    target = total // 2
    dp = set([0])  # Set storing all achievable subset sums

    for num in nums:
        next_dp = set(dp)
        for t in dp:
            if t + num == target:
                return True
            if t + num < target:
                next_dp.add(t + num)
        dp = next_dp
    return target in dp

