def checkValidString(s: str) -> bool:
    # Range of possible open parentheses: [cmin, cmax]
    cmin, cmax = 0, 0
    for c in s:
        if c == "(":
            cmin += 1
            cmax += 1
        elif c == ")":
            cmin -= 1
            cmax -= 1
        else: # c == '*' (can be '(', ')', or '')
            cmin -= 1
            cmax += 1
        if cmax < 0:
            return False  # More ')' than '(' possible
        cmin = max(cmin, 0)
    return cmin == 0

