def myPow(x: float, n: int) -> float:
    # Binary Exponentiation (Exponentiation by Squaring) in O(log n)
    if n < 0:
        x = 1 / x
        n = -n
    res = 1.0
    curr = x
    while n > 0:
        if n % 2 == 1:
            res *= curr
        curr *= curr  # Square base
        n //= 2       # Halve exponent
    return res

